// File: src/components/ReferralHistoryTable.jsx
import React, { useEffect, useState } from "react";
import axios from "axios";

// API base URL from .env
const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || "http://localhost:8080";

export default function ReferralHistoryTable({ isAdmin = false }) {
  const [referrals, setReferrals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    fetchReferralHistory();
  }, [isAdmin]);

  const fetchReferralHistory = async () => {
    setLoading(true);
    setError("");

    try {
      const token = localStorage.getItem("authToken");
      if (!token) throw new Error("User not authenticated");

      // ✅ User sees own referral bonuses, Admin sees all referrals
      const endpoint = isAdmin
        ? `${API_BASE_URL}/api/bonus-history/all-referrals`
        : `${API_BASE_URL}/api/bonus-history/my-referrals`;

      const res = await axios.get(endpoint, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!Array.isArray(res.data)) throw new Error("Invalid response data");

      const referralData = res.data
        .filter(item => item && item.type && item.type.toLowerCase() === "referral")
        .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

      setReferrals(referralData);
    } catch (err) {
      console.error("Error fetching referral history:", err);
      setError("Failed to load referral history. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center py-10">
        <p className="text-gray-500 text-lg animate-pulse">Loading referral history...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex justify-center items-center py-10">
        <p className="text-red-500 text-lg">{error}</p>
      </div>
    );
  }

  if (referrals.length === 0) {
    return (
      <div className="flex justify-center items-center py-10">
        <p className="text-gray-500 text-lg">No referral bonuses yet.</p>
      </div>
    );
  }

  return (
    <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
      <h2 className="text-3xl font-bold text-center text-gray-800 mb-6">
        {isAdmin ? "All Users Referral History" : "Your Referral Bonus History"}
      </h2>
      <div className="overflow-x-auto shadow-lg rounded-lg border border-gray-200">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-100">
            <tr>
              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-700">#</th>
              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-700">User / Referrer</th>
              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-700">Bonus Amount</th>
              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-700">Date</th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {referrals.map((item, index) => (
              <tr key={index} className="hover:bg-gray-50 transition-colors duration-200">
                <td className="px-6 py-4 text-gray-800">{index + 1}</td>
                <td className="px-6 py-4 text-gray-800 font-medium">{item.sourceGameId || item.userGameId || "N/A"}</td>
                <td className="px-6 py-4 text-green-600 font-bold">
                  {Number(item.amount || 0).toLocaleString()} ৳
                </td>
                <td className="px-6 py-4 text-gray-500">
                  {item.createdAt ? new Date(item.createdAt).toLocaleString() : "N/A"}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
